package org.keyblock.tr31;

import java.security.SecureRandom;

import at.favre.lib.bytes.Bytes;

/**
 * Generation of Key Block Protection Keys and clear keys, for use as test vectors and when
 * bringing up a key block implementation.
 * <p>
 * These use a shared {@link SecureRandom}. They must not be used to generate production key
 * material, the protection keys in particular are normally provisioned through a secure channel
 * rather than generated by the application.
 */
public final class RandomKeys {

    private static final SecureRandom RANDOM = new SecureRandom();

    private RandomKeys() { }

    /**
     * Generate a Key Block Protection Key of a length valid for the key block type.
     *
     * @param type
     *            the key block type the key will protect
     * @param keyLengthBits
     *            128 or 192 for the TDEA types A, B and C, or 128, 192 or 256 for the AES types D
     *            and E
     * @return the key as uppercase hexadecimal
     */
    public static String generateKBPK(KeyblockType type, int keyLengthBits) {
        switch (type) {
            case _A_KEY_VARIANT_BINDING:
            case _B_TDEA_KEY_DERIVATION_BINDING:
            case _C_TDEA_KEY_VARIANT_BINDING:
            case _0_THALES_DES: {
                if (keyLengthBits != 128 && keyLengthBits != 192) {
                    throw new IllegalArgumentException(
                            "A TDEA key block protection key must be 128 or 192 bits");
                }
                break;
            }
            case _D_AES_KEY_DERIVATION:
            case _E_ISO20038_AES_KEY_DERIVATION:
            case _1_THALES_AES: {
                if (keyLengthBits != 128 && keyLengthBits != 192 && keyLengthBits != 256) {
                    throw new IllegalArgumentException(
                            "An AES key block protection key must be 128, 192 or 256 bits");
                }
                break;
            }
            default: {
                throw new IllegalArgumentException("Unsupported key block type " + type);
            }
        }

        return randomHex(keyLengthBits / 8);
    }

    /**
     * Generate a clear key of a length valid for the algorithm.
     *
     * @param algorithm
     *            the algorithm the key will be used with
     * @param keyLengthBits
     *            128 or 192 for TDEA, 128, 192 or 256 for AES, 64 for single DES
     * @return the key as uppercase hexadecimal
     */
    public static String generateClearKey(Algorithm algorithm, int keyLengthBits) {
        switch (algorithm) {
            case _T_TRIPLE_DES: {
                if (keyLengthBits != 128 && keyLengthBits != 192) {
                    throw new IllegalArgumentException("A TDEA key must be 128 or 192 bits");
                }
                break;
            }
            case _A_AES: {
                if (keyLengthBits != 128 && keyLengthBits != 192 && keyLengthBits != 256) {
                    throw new IllegalArgumentException("An AES key must be 128, 192 or 256 bits");
                }
                break;
            }
            case _D_DEA: {
                if (keyLengthBits != 64) {
                    throw new IllegalArgumentException("A DES key must be 64 bits");
                }
                break;
            }
            default: {
                throw new IllegalArgumentException("Cannot generate a key for algorithm " + algorithm);
            }
        }

        return randomHex(keyLengthBits / 8);
    }

    private static String randomHex(int byteLength) {
        byte[] bytes = new byte[byteLength];
        RANDOM.nextBytes(bytes);
        return Bytes.from(bytes)
                    .encodeHex(true);
    }
}